<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_student();$uid=(int)current_user()['user_id'];$start=valid_date((string)($_GET['start']??''))?$_GET['start']:date('Y-m-d',strtotime('-29 days'));$end=valid_date((string)($_GET['end']??''))?$_GET['end']:date('Y-m-d');$type=$_GET['type']??'all';$cat=(int)($_GET['category_id']??0);$where=['t.user_id=?','t.status="active"','t.transaction_date BETWEEN ? AND ?'];$params=[$uid,$start,$end];if(in_array($type,['income','expense'],true)){$where[]='t.type=?';$params[]=$type;}if($cat>0){$where[]='t.category_id=?';$params[]=$cat;}$s=db()->prepare('SELECT t.*,c.name category FROM transactions t JOIN categories c ON c.category_id=t.category_id WHERE '.implode(' AND ',$where).' ORDER BY t.transaction_date');$s->execute($params);$rows=$s->fetchAll();$cats=array_merge(user_categories($uid,'income'),user_categories($uid,'expense'));$income=$expense=0;$daily=[];foreach($rows as$r){${$r['type']}+=(float)$r['amount'];$daily[$r['transaction_date']]=$daily[$r['transaction_date']]??['income'=>0,'expense'=>0];$daily[$r['transaction_date']][$r['type']]+=(float)$r['amount'];}$pageTitle='Reports';$activePage='reports';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">REPORT CENTER</span><h1>Reports</h1><p>Explore your period and use the browser print dialog to save a PDF.</p></div><div class="report-actions"><button type="button" class="btn btn-ghost" onclick="window.print()">Print / Save PDF</button><button type="button" class="btn btn-ghost" onclick="downloadReportChart()">Save chart image</button><a class="btn btn-ghost" href="<?=e(url('student/reports.php?start='.date('Y-m-d',strtotime('-5 months')).'&end='.date('Y-m-d')))?>">Last 6 months</a></div></section><section class="panel"><form class="filter-bar"><input class="input" type="date" name="start" value="<?=e($start)?>"><input class="input" type="date" name="end" value="<?=e($end)?>"><select class="input" name="type"><option value="all">All</option><option value="income" <?=$type==='income'?'selected':''?>>Income</option><option value="expense" <?=$type==='expense'?'selected':''?>>Expense</option></select><select class="input" name="category_id"><option value="0">All categories</option><?php foreach($cats as$c):?><option value="<?=$c['category_id']?>" <?=$cat===$c['category_id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Apply</button></form></section><div class="report-summary"><div><span>Income</span><strong class="text-green"><?=money($income)?></strong></div><div><span>Expense</span><strong class="text-red"><?=money($expense)?></strong></div><div><span>Balance</span><strong><?=money($income-$expense)?></strong></div><div><span>Records</span><strong><?=count($rows)?></strong></div></div><div class="dashboard-grid"><section class="panel span-8"><div class="panel-head"><div><span class="panel-kicker">DAILY VIEW</span><h2>Activity across the period</h2></div></div><div class="chart-box"><canvas id="reportChart"></canvas></div></section><section class="panel span-4"><div class="panel-head"><div><span class="panel-kicker">BREAKDOWN</span><h2>Latest records</h2></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Amount</th></tr></thead><tbody><?php foreach(array_slice($rows,-10) as$r):?><tr><td><?=e(date('d M',strtotime($r['transaction_date'])))?></td><td><?=e($r['category'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><script>window.REPORT_DATA=<?=json_encode((function()use($start,$end,$daily){$l=[];$vi=[];$ve=[];$d=$start;while($d<=$end){$l[]=date('d M',strtotime($d));$vi[]=$daily[$d]['income']??0;$ve[]=$daily[$d]['expense']??0;$d=date('Y-m-d',strtotime($d.' +1 day'));}return ['labels'=>$l,'income'=>$vi,'expense'=>$ve];})(),JSON_UNESCAPED_UNICODE)?>;function downloadReportChart(){const c=document.getElementById('reportChart');if(!c)return;const a=document.createElement('a');a.download='campus-coin-report.png';a.href=c.toDataURL('image/png');a.click();}
</script><?php require __DIR__.'/../includes/footer.php';?>